package com.example.tracker.common.json;

import org.tentackle.common.TentackleRuntimeException;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A minimal JSON reader (see RFC 8259).
 * <p>
 * Just enough to read the small documents exchanged during single sign-on: the token response of
 * the authorization server, the JWKS document and the claims of a JWT. Tentackle does not ship a
 * JSON parser and pulling in one of the usual libraries would drag a whole dependency tree into
 * the modular build, so this is deliberately hand-written and dependency free.
 * <p>
 * Values are mapped as follows:
 * <ul>
 *   <li>object &rarr; {@link Map} (insertion ordered)</li>
 *   <li>array &rarr; {@link List}</li>
 *   <li>string &rarr; {@link String}</li>
 *   <li>number &rarr; {@link Long} if integral, else {@link Double}</li>
 *   <li>true/false &rarr; {@link Boolean}</li>
 *   <li>null &rarr; {@code null}</li>
 * </ul>
 */
public final class Json {

  /**
   * Parses a JSON document that must be an object.
   *
   * @param text the JSON text
   * @return the parsed object, never null
   * @throws TentackleRuntimeException if the text is malformed or not an object
   */
  @SuppressWarnings("unchecked")
  public static Map<String, Object> parseObject(String text) {
    Object value = parse(text);
    if (value instanceof Map) {
      return (Map<String, Object>) value;
    }
    throw new TentackleRuntimeException("JSON object expected");
  }

  /**
   * Parses a JSON document.
   *
   * @param text the JSON text
   * @return the parsed value, may be null
   * @throws TentackleRuntimeException if the text is malformed
   */
  public static Object parse(String text) {
    if (text == null) {
      throw new TentackleRuntimeException("no JSON text");
    }
    Parser parser = new Parser(text);
    Object value = parser.parseValue();
    parser.skipWhitespace();
    if (!parser.atEnd()) {
      throw parser.error("trailing garbage");
    }
    return value;
  }


  /**
   * Gets a string member.
   *
   * @param object the JSON object
   * @param key the member name
   * @return the string, null if absent or not a string
   */
  public static String getString(Map<String, Object> object, String key) {
    Object value = object.get(key);
    return value instanceof String str ? str : null;
  }

  /**
   * Gets an integral member.
   *
   * @param object the JSON object
   * @param key the member name
   * @param defaultValue the value to return if the member is absent or not a number
   * @return the number
   */
  public static long getLong(Map<String, Object> object, String key, long defaultValue) {
    Object value = object.get(key);
    return value instanceof Number number ? number.longValue() : defaultValue;
  }

  /**
   * Gets a boolean member.
   * <p>
   * Some authorization servers send booleans as strings, which is accepted as well.
   *
   * @param object the JSON object
   * @param key the member name
   * @return true if the member is boolean true or the string "true"
   */
  public static boolean getBoolean(Map<String, Object> object, String key) {
    Object value = object.get(key);
    if (value instanceof Boolean bool) {
      return bool;
    }
    return value instanceof String str && Boolean.parseBoolean(str);
  }

  /**
   * Gets an array member.
   *
   * @param object the JSON object
   * @param key the member name
   * @return the list, empty if absent or not an array
   */
  @SuppressWarnings("unchecked")
  public static List<Object> getList(Map<String, Object> object, String key) {
    Object value = object.get(key);
    return value instanceof List ? (List<Object>) value : List.of();
  }

  /**
   * Gets an object member.
   *
   * @param object the JSON object
   * @param key the member name
   * @return the object, null if absent or not an object
   */
  @SuppressWarnings("unchecked")
  public static Map<String, Object> getObject(Map<String, Object> object, String key) {
    Object value = object.get(key);
    return value instanceof Map ? (Map<String, Object>) value : null;
  }


  private Json() {
  }


  /**
   * A recursive descent parser over the JSON text.
   */
  private static final class Parser {

    private final String text;
    private int pos;

    private Parser(String text) {
      this.text = text;
    }

    private boolean atEnd() {
      return pos >= text.length();
    }

    private TentackleRuntimeException error(String message) {
      return new TentackleRuntimeException("malformed JSON at offset " + pos + ": " + message);
    }

    private void skipWhitespace() {
      while (pos < text.length()) {
        char c = text.charAt(pos);
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
          pos++;
        }
        else {
          break;
        }
      }
    }

    private char next() {
      if (atEnd()) {
        throw error("unexpected end of text");
      }
      return text.charAt(pos++);
    }

    private void expect(char expected) {
      char c = next();
      if (c != expected) {
        pos--;
        throw error("'" + expected + "' expected");
      }
    }

    private Object parseValue() {
      skipWhitespace();
      if (atEnd()) {
        throw error("unexpected end of text");
      }
      char c = text.charAt(pos);
      return switch (c) {
        case '{' -> parseObject();
        case '[' -> parseArray();
        case '"' -> parseString();
        case 't' -> parseKeyword("true", Boolean.TRUE);
        case 'f' -> parseKeyword("false", Boolean.FALSE);
        case 'n' -> parseKeyword("null", null);
        default  -> parseNumber();
      };
    }

    private Object parseKeyword(String keyword, Object value) {
      if (!text.startsWith(keyword, pos)) {
        throw error("'" + keyword + "' expected");
      }
      pos += keyword.length();
      return value;
    }

    private Map<String, Object> parseObject() {
      expect('{');
      Map<String, Object> object = new LinkedHashMap<>();
      skipWhitespace();
      if (!atEnd() && text.charAt(pos) == '}') {
        pos++;
        return object;
      }
      while (true) {
        skipWhitespace();
        String name = parseString();
        skipWhitespace();
        expect(':');
        object.put(name, parseValue());
        skipWhitespace();
        char c = next();
        if (c == '}') {
          return object;
        }
        if (c != ',') {
          pos--;
          throw error("',' or '}' expected");
        }
      }
    }

    private List<Object> parseArray() {
      expect('[');
      List<Object> array = new ArrayList<>();
      skipWhitespace();
      if (!atEnd() && text.charAt(pos) == ']') {
        pos++;
        return array;
      }
      while (true) {
        array.add(parseValue());
        skipWhitespace();
        char c = next();
        if (c == ']') {
          return array;
        }
        if (c != ',') {
          pos--;
          throw error("',' or ']' expected");
        }
      }
    }

    private String parseString() {
      expect('"');
      StringBuilder buf = new StringBuilder();
      while (true) {
        char c = next();
        if (c == '"') {
          return buf.toString();
        }
        if (c == '\\') {
          char escaped = next();
          switch (escaped) {
            case '"'  -> buf.append('"');
            case '\\' -> buf.append('\\');
            case '/'  -> buf.append('/');
            case 'b'  -> buf.append('\b');
            case 'f'  -> buf.append('\f');
            case 'n'  -> buf.append('\n');
            case 'r'  -> buf.append('\r');
            case 't'  -> buf.append('\t');
            case 'u'  -> {
              if (pos + 4 > text.length()) {
                throw error("truncated unicode escape");
              }
              try {
                buf.append((char) Integer.parseInt(text, pos, pos + 4, 16));
              }
              catch (NumberFormatException nfx) {
                throw error("invalid unicode escape");
              }
              pos += 4;
            }
            default -> {
              pos--;
              throw error("invalid escape sequence");
            }
          }
        }
        else if (c < 0x20) {
          pos--;
          throw error("unescaped control character");
        }
        else {
          buf.append(c);
        }
      }
    }

    private Object parseNumber() {
      int start = pos;
      if (!atEnd() && text.charAt(pos) == '-') {
        pos++;
      }
      boolean integral = true;
      while (!atEnd()) {
        char c = text.charAt(pos);
        if (c >= '0' && c <= '9') {
          pos++;
        }
        else if (c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-') {
          integral = false;
          pos++;
        }
        else {
          break;
        }
      }
      if (pos == start) {
        throw error("number expected");
      }
      String number = text.substring(start, pos);
      try {
        return integral ? (Object) Long.valueOf(number) : (Object) Double.valueOf(number);
      }
      catch (NumberFormatException nfx) {
        pos = start;
        throw error("invalid number '" + number + "'");
      }
    }
  }

}
